// Import of required libraries
import { test, expect, SkyrampClient, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    createUser,
    createCollection,
    updateCollection,
    getCollectionMembers,
    transferCollectionOwnership,
    getCollectionTransfer,
    deleteUser,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const targetUsername = uniqueSuffix("transfertarget");
    const nonMemberUsername = uniqueSuffix("transfernonmember");
    const collectionName = uniqueSuffix("Transfer Workflow");

    const usersPostResponse = await createUser(client, headers, targetUsername, "Transfer Target");
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'target username').toBe(targetUsername);
    expect(getResponseValue(usersPostResponse, "response.id"), 'target user id').toBeGreaterThan(0);
    const targetUserId = getResponseValue(usersPostResponse, "response.id");

    const usersPost1Response = await createUser(client, headers, nonMemberUsername, "Non Member");
    expect(usersPost1Response.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPost1Response, "response.username"), 'non-member username').toBe(nonMemberUsername);
    expect(getResponseValue(usersPost1Response, "response.id"), 'non-member user id').toBeGreaterThan(0);
    const nonMemberUserId = getResponseValue(usersPost1Response, "response.id");

    const collectionsPostResponse = await createCollection(client, headers, collectionName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe(collectionName);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection id').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const originalOwnerId = getResponseValue(collectionsPostResponse, "response.ownerId");

    // A user who is not yet a member of the collection cannot receive ownership.
    const collectionsTransferPostResponse = await transferCollectionOwnership(client, headers, collectionId, nonMemberUserId, 400);
    expect(collectionsTransferPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsTransferPostResponse, "response"), 'non-member rejection').toBe("Transfer target must already be a member of the collection.");

    // A transfer with no toUserId is rejected.
    const collectionsTransferPost1Response = await transferCollectionOwnership(client, headers, collectionId, null, 400);
    expect(collectionsTransferPost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsTransferPost1Response, "response"), 'missing toUserId rejection').toBe("toUserId is required.");

    // A collection that does not exist is rejected.
    const transferPostResponse = await transferCollectionOwnership(client, headers, 99999999, targetUserId, 404);
    expect(transferPostResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(transferPostResponse, "response"), 'unknown collection rejection').toBe("Collection not found.");

    // Only POST is allowed on the transfer endpoint.
    const collectionsTransferGetResponse = await getCollectionTransfer(client, headers, collectionId, 405);
    expect(collectionsTransferGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(collectionsTransferGetResponse, "response"), 'method rejection').toBe("Method not allowed.");

    // Make the target a member so the transfer precondition is satisfied.
    const collectionsCollectionsPutResponse = await updateCollection(client, headers, collectionId, collectionName, targetUserId);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members").length, 'member count').toBe(1);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.userId"), 'member').toBe(targetUserId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.ownerId"), 'owner before the transfer').toBe(originalOwnerId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.1"), 'no second member').toBeNull();

    // The transfer moves ownership to the member.
    const collectionsTransferPost2Response = await transferCollectionOwnership(client, headers, collectionId, targetUserId, 200);
    expect(collectionsTransferPost2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsTransferPost2Response, "response.id"), 'transferred collection id').toBe(collectionId);
    expect(getResponseValue(collectionsTransferPost2Response, "response.name"), 'transferred collection name').toBe(collectionName);
    expect(getResponseValue(collectionsTransferPost2Response, "response.ownerId"), 'new owner').toBe(targetUserId);

    // The previous owner can no longer manage the collection, which proves ownership actually moved.
    const membersGetResponse = await getCollectionMembers(client, headers, collectionId, 403);
    expect(membersGetResponse.statusCode, 'status code').toBe(403);
    expect(getResponseValue(membersGetResponse, "response"), 'previous owner is refused').toBe("Only the owner can manage members.");

    // Deleting the new owner cascades the collection they now own.
    const usersUsersDeleteResponse = await deleteUser(client, headers, targetUserId);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'target deletion message').toBe("User account and all related data deleted successfully.");

    const usersUsersDelete1Response = await deleteUser(client, headers, nonMemberUserId);
    expect(usersUsersDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDelete1Response, "response"), 'non-member deletion message').toBe("User account and all related data deleted successfully.");
});
